1	import { Injectable } from '@nestjs/common';
2	import { CheckoutPaymentIntent } from '@paypal/paypal-server-sdk';
3	import { ID, Logger, OrderService, RequestContext, UserInputError } from '@vendure/core';
4	import { getOrdersController } from './paypal-client';
5	import { toPayPalAmount } from './utils/currency';
6	
7	const loggerCtx = 'PayPalService';
8	
9	@Injectable()
10	export class PayPalService {
11	    constructor(private readonly orderService: OrderService) {}
12	
13	    /**
14	     * Creates a PayPal order for the caller's active Vendure order.
15	     * Returns the PayPal order ID and the buyer-approval URL.
16	     */
17	    async createPayPalOrder(ctx: RequestContext): Promise<{ paypalOrderId: string; approvalUrl: string }> {
18	        const activeOrderId = ctx.session?.activeOrderId;
19	        if (!activeOrderId) {
20	            throw new UserInputError('No active order found. Add items to your cart first.');
21	        }
22	
23	        const order = await this.orderService.findOne(ctx, activeOrderId as ID);
24	        if (!order) {
25	            throw new UserInputError(`Active order ${activeOrderId} not found.`);
26	        }
27	
28	        const currencyCode = String(order.currencyCode);
29	        const value = toPayPalAmount(order.totalWithTax, currencyCode);
30	
31	        Logger.info(
32	            `Creating PayPal order for Vendure order ${order.code}: ${currencyCode} ${value}`,
33	            loggerCtx,
34	        );
35	
36	        const ordersController = getOrdersController();
37	
38	        const response = await ordersController.createOrder({
39	            body: {
40	                intent: CheckoutPaymentIntent.Capture,
41	                purchaseUnits: [
42	                    {
43	                        referenceId: order.code,
44	                        amount: {
45	                            currencyCode,
46	                            value,
47	                        },
48	                    },
49	                ],
50	            },
51	            prefer: 'return=representation',
52	        });
53	
54	        const paypalOrder = response.result;
55	
56	        if (!paypalOrder?.id) {
57	            throw new Error('PayPal did not return an order ID.');
58	        }
