                // to know where to send the buyer after approval or cancellation.
                paymentSource: {
                    paypal: {
                        experienceContext: {
                            returnUrl,
                            cancelUrl,
                            userAction: PaypalExperienceUserAction.PayNow,
                        },
                    },
                },
            },
