import { Mutation, Resolver } from '@nestjs/graphql';
import { Allow, Ctx, Permission, RequestContext } from '@vendure/core';
import { PayPalService } from '../paypal.service';

@Resolver()
export class PayPalShopResolver {
    constructor(private readonly paypalService: PayPalService) {}

    /**
     * Creates a PayPal order for the caller's active cart and returns the PayPal order ID
     * along with the buyer-approval URL.
     *
     * The storefront must redirect (or open a popup) to `approvalUrl` so the buyer can
     * approve the payment on PayPal.  Once approved, call `addPaymentToOrder` with
     * `method: 'paypal-payment-handler'` and `metadata: { paypalOrderId }`.
     */
    @Mutation()
    @Allow(Permission.Owner)
    createPayPalOrder(@Ctx() ctx: RequestContext) {
        return this.paypalService.createPayPalOrder(ctx);
    }
}

content.text:
No output = zero errors in the plugin files. Exit code 2 is from the same pre-existing errors in `reviews`/`dashboard` as before.

---

## Use Case 2 is implemented and self-tested.

### What changed

| File | Change |
|------|--------|
| `paypal-client.ts` | Added `getPaymentsController()` — needed for `captureAuthorizedPayment` |
| `payment/paypal-payment.handler.ts` | `createPayment` branches on `metadata.intent === 'AUTHORIZE'` → calls `authorizeOrder` → returns `state: 'Authorized'`; `settlePayment` now captures the authorization when `authorizationId` is present in metadata |
| `paypal.service.ts` | Refactored into a shared `buildPayPalOrder(intent)` private method; added `createPayPalOrderForAuthorization` |
| `api/shop-api.extensions.ts` | Added `createPayPalOrderForAuthorization` mutation |
| `api/paypal-shop.resolver.ts` | Added resolver method for the new mutation |

---

### How to manually verify via Postman

**Step 1 — Create the authorization order (Shop API)**

```graphql
mutation {
  createPayPalOrderForAuthorization {
    paypalOrderId
    approvalUrl
  }
}
```
**Expected:** `paypalOrderId` + `approvalUrl` pointing to `sandbox.paypal.com`.

---

**Step 2 — Buyer approves on PayPal**

Open the `approvalUrl`, log in as sandbox buyer, click **Pay Now**. You'll be redirected to `PAYPAL_RETURN_URL?token=<paypalOrderId>&PayerID=...`. Copy the `token`.

---

**Step 3 — Authorize (reserve) the funds**

```graphql
mutation {
  addPaymentToOrder(input: {
    method: "paypal"
    metadata: {
      paypalOrderId: "PASTE_TOKEN_HERE"
      intent: "AUTHORIZE"
    }
  }) {
    ... on Order {
      state
      payments {
        id
        state
        transactionId
        metadata
      }
    }
  }
}
```
**Expected:** Order state `PaymentAuthorized`, payment state `Authorized`, `metadata.authorizationId` present, no money moved yet.

---

**Step 4 — Capture (settle) via Admin API when ready to ship**

```graphql
# Admin API
mutation {
  settlePayment(id: "PAYMENT_ID_FROM_STEP_3") {
    ... on Payment {
      id
      state
      metadata
    }
    ... on SettlePaymentError { message }
  }
}
```
**Expected:** Payment state transitions to `Settled`, `metadata.captureId` and `captureStatus: "COMPLETED"` added — funds are now moved.

---

When you've confirmed this works, reply **"Okay, proceed to the next usecase"** and I'll implement **Use Case 3 — Payment Cancellation / Void**.

