    CreateBillingPlanInput,
    PayPalSubscriptionService,
} from '../subscription/paypal-subscription.service';

@Resolver()
export class PayPalAdminResolver {
    constructor(private readonly subscriptionService: PayPalSubscriptionService) {}

    @Query()
